function Savings({goals,add,del,edit,update}:{goals:Goal[];add:()=>void;del:(i:string,t:string)=>void;edit:(id:string)=>void;update:(i:string,n:number)=>void}){const groups:GoalCategory[]=['Sparemål','Buffer','Fond','Aksjer','Pensjon'];return <><Summary k="SAMLET SPARING" a={kr(goals.reduce((a,b)=>a+b.saved,0))} d={kr(goals.reduce((a,b)=>a+b.monthly,0))+' fast sparing per måned'}/><Section title="Sparing og investering" action="Legg til" onPress={add}/>{groups.map(c=>{const list=goals.filter(g=>g.category===c).sort((a,b)=>(b.monthly-a.monthly)||(b.saved-a.saved));return list.length?<View key={c}><Text style={S.groupTitle}>{c}</Text>{list.map(g=><GoalCard key={g.id} g={g} del={()=>del(g.id,g.name)} edit={()=>edit(g.id)} update={n=>update(g.id,n)}/>)}</View>:null})}</>}
function GoalCard({g,del,edit,update}:{g:Goal;del:()=>void;edit:()=>void;update:(n:number)=>void}){
 const[pay,setPay]=useState(Math.max(500,g.monthly||1000));const[showExtra,setShowExtra]=useState(false);const usesTarget=goalUsesTarget(g.category);const hasTarget=g.target>0;const pct=hasTarget?Math.round(g.saved/g.target*100):0;const remaining=Math.max(0,g.target-g.saved);const months=usesTarget&&hasTarget&&remaining>0&&g.monthly>0?Math.ceil(remaining/g.monthly):null;const forecast=!usesTarget?(g.category==='Pensjon'?'Langsiktig pensjonssparing uten krav om måloppnåelse':`Fast ${g.category.toLowerCase()}sparing uten krav om måloppnåelse`):!hasTarget?'Legg inn et målbeløp for å se prognose':remaining<=0?'Målet er nådd':months!==null?`Ca. ${durationText(months)} igjen med dagens sparing`:'Legg inn fast månedlig sparing for å se prognose';const targetDate=parseDate(g.targetDate);const now=new Date();const monthsToDate=targetDate?Math.max(0,(targetDate.getFullYear()-now.getFullYear())*12+(targetDate.getMonth()-now.getMonth())+(targetDate.getDate()>now.getDate()?1:0)):0;const requiredMonthly=usesTarget&&hasTarget&&remaining>0&&monthsToDate>0?Math.ceil(remaining/monthsToDate):null;const planText=!usesTarget||!hasTarget||!targetDate?'':remaining<=0?'Målbeløpet er allerede nådd.':monthsToDate<=0?'Måldatoen er passert.':requiredMonthly!==null?g.monthly>=requiredMonthly?`Du ligger i rute. Minst ca. ${kr(requiredMonthly)}/mnd trengs frem til måldatoen.`:`For å nå målet innen måldatoen bør du spare ca. ${kr(requiredMonthly)}/mnd. Det er ca. ${kr(requiredMonthly-g.monthly)}/mnd mer enn dagens sparing.`:'';
 return <View style={S.goal}>{g.imageUri?<ImageBackground source={{uri:g.imageUri}} style={S.goalImage} imageStyle={S.goalImageInner}><View style={S.overlay}/><View style={S.goalText}><Text style={S.goalLight}>{g.name}</Text><Text style={S.goalMeta}>{g.category}{g.targetDate?` • ${g.targetDate}`:''}</Text></View></ImageBackground>:<View style={S.goalFallback}><Ionicons name={goalIcon(g)} size={32} color={C.green}/><View style={S.flex}><Text style={S.groupTitle}>{g.name}</Text><Text style={S.cardSub}>{g.category}{g.targetDate?` • ${g.targetDate}`:''}</Text></View></View>}<View style={S.trashFloat}><Pressable onPress={edit} accessibilityRole="button" accessibilityLabel={`Rediger ${g.name}`} style={S.editMini}><Ionicons name="pencil-outline" size={18} color={C.green}/></Pressable><Trash onPress={del}/></View><View style={S.goalBody}><Text style={S.goalAmount}>{kr(g.saved)}{usesTarget&&hasTarget?<Text style={S.goalTarget}> av {kr(g.target)}</Text>:null}</Text>{usesTarget&&hasTarget?<><Progress val={Math.min(100,pct)}/><Text style={S.cardSub}>{pct}% • fast {kr(g.monthly)}/mnd • inkludert i budsjettet</Text></>:<Text style={S.cardSub}>Fast {kr(g.monthly)}/mnd • inkludert i budsjettet</Text>}<View style={S.goalForecast}><Ionicons name={remaining<=0&&usesTarget&&hasTarget?'checkmark-circle-outline':'time-outline'} size={18} color={C.green}/><Text style={S.goalForecastText}>{forecast}</Text></View>{planText?<View style={S.goalPlan}><Ionicons name={g.monthly>=Number(requiredMonthly||0)?'checkmark-circle-outline':'calculator-outline'} size={18} color={C.green}/><Text style={S.goalPlanText}>{planText}</Text></View>:null}<Pressable onPress={()=>setShowExtra(v=>!v)} style={S.extraToggle}><Text style={S.extraToggleText}>{showExtra?'Skjul ekstra innbetaling':'Legg til ekstra innbetaling'}</Text><Ionicons name={showExtra?'chevron-up':'chevron-down'} size={17} color={C.green}/></Pressable>{showExtra?<View style={S.sliderBox}><View style={S.rowBetween}><Text style={S.cardSub}>Ekstra innbetaling</Text><Text style={S.value}>{kr(pay)}</Text></View><Slider minimumValue={0} maximumValue={10000} step={100} value={pay} onValueChange={setPay} minimumTrackTintColor={C.green} maximumTrackTintColor="#D9E2DD" thumbTintColor={C.green}/><Pressable onPress={()=>{update(pay);setShowExtra(false)}} accessibilityRole="button" accessibilityLabel="Registrer ekstra innbetaling" style={S.primarySmall}><Text style={S.primaryText}>Registrer innbetaling</Text></Pressable></View>:null}</View></View>}

function Form({kind,initial,editing,close,saveInsurance,saveSubscription,saveGoal,saveIncome,saveExpense}:{kind:FormKind;initial?:any;editing:boolean;close:()=>void;saveInsurance:(x:Omit<Insurance,'id'>)=>void;saveSubscription:(x:Omit<Subscription,'id'>)=>void;saveGoal:(x:Omit<Goal,'id'>)=>void;saveIncome:(x:Omit<BudgetItem,'id'>)=>void;saveExpense:(x:Omit<BudgetItem,'id'>)=>void}){
 const[f,setF]=useState<Record<string,string>>({});const[cat,setCat]=useState<GoalCategory>('Sparemål');const[moreInsurance,setMoreInsurance]=useState(false);const[expenseGroup,setExpenseGroup]=useState<string|null>(null);const[incomeGroup,setIncomeGroup]=useState<string|null>(null);const[subscriptionGroup,setSubscriptionGroup]=useState<string|null>(null);const[incomePeriod,setIncomePeriod]=useState<Period>('month');const[expensePeriod,setExpensePeriod]=useState<Period>('month');const[subscriptionPeriod,setSubscriptionPeriod]=useState<Period>('month');const[showSubscriptionDate,setShowSubscriptionDate]=useState(false);const[insurancePeriod,setInsurancePeriod]=useState<Period>('month');const[showInsuranceStartDate,setShowInsuranceStartDate]=useState(false);const[showInsuranceExpiryDate,setShowInsuranceExpiryDate]=useState(false);const[showGoalDate,setShowGoalDate]=useState(false);
 const incomeTypes:[string,string[]][]=[['Arbeid',['Lønn','Overtid / tillegg','Bonus','Næringsinntekt']],['Trygd',['Barnetrygd','Kontantstøtte','Foreldrepenger','Barnebidrag','Sykepenger','Dagpenger','Pensjon','NAV / trygd']],['Studier',['Stipend','Studielån']],['Kapital og eiendom',['Leieinntekt','Renteinntekt','Utbytte']],['Annet',['Annen inntekt']]];
 const expenseTypes:[string,string[]][]=[['Bolig',['Boliglån','Husleie','Strøm','Kommunale avgifter']],['Forsikringer',['Husforsikring','Innboforsikring','Bilforsikring','Reiseforsikring','Livsforsikring','Ulykkesforsikring','Annen forsikring']],['Abonnement',['Mobil','Internett','TV / streaming','Musikk','Skylagring','Programvare','Avis / nyheter','Gaming','Annet abonnement']],['Mat og husholdning',['Mat og dagligvarer','Husholdningsartikler']],['Barn',['Barnehage / SFO','Klær og utstyr','Fritidsaktiviteter']],['Transport',['Billån','Drivstoff / lading','Bom / parkering','Kollektivtransport']],['Gjeld',['Studielån','Kredittkort / lån']],['Helse og fritid',['Medisiner / behandling','Trening','Restaurant / takeaway','Klær og sko']],['Annet',['Gaver','Kjæledyr','Uforutsette utgifter','Annen utgift']]];
 const insuranceTypes=['Husforsikring','Innboforsikring','Bilforsikring','Reiseforsikring','Livsforsikring','Ulykkesforsikring','Dyreforsikring','Annen forsikring'];
 const insuranceProviders=['DNB','Gjensidige','If','Tryg','Fremtind','Frende','Storebrand','KLP','Eika','JBF','WaterCircles','Annet selskap'];
 const subscriptionTypes:[string,string[]][]=[['TV / streaming',['Netflix','Max','Disney+','TV 2 Play','Viaplay','YouTube Premium','Annen strømmetjeneste']],['Musikk',['Spotify','Apple Music','YouTube Music','Tidal','Annen musikktjeneste']],['Mobil',['Telenor','Telia','ice','Talkmore','OneCall','Chilimobil','Annet mobilabonnement']],['Internett',['Telenor','Telia','Altibox','NextGenTel','GlobalConnect','Annet internettabonnement']],['Programvare',['Microsoft 365','Adobe','Google One','Dropbox','Annen programvare']],['Gaming',['PlayStation Plus','Xbox Game Pass','Nintendo Switch Online','EA Play','Annet gamingabonnement']],['Avis / nyheter',['VG+','Aftenposten','DN','Tønsbergs Blad','Annet nyhetsabonnement']],['Skylagring',['iCloud+','Google One','Dropbox','OneDrive','Annen skylagring']],['Trening',['Treningssenter','Treningsapp','Annet treningsabonnement']],['Annet',['Annet abonnement']]];
 const set=(k:string,v:string)=>setF(x=>({...x,[k]:v}));
 useEffect(()=>{const i=initial||{};setF(kind==='insurance'?{name:i.type||'',provider:i.provider||'',monthly:(i.registeredAmount??i.monthly)?groupDigits(String(i.registeredAmount??i.monthly)):'',bonus:i.bonus||'',coverageType:i.coverageType||i.coverage||'',insuredValue:i.insuredValue||'',deductible:i.deductible||'',startDate:i.startDate||'',expiryDate:i.expiryDate||i.renewal||'',note:i.note||''}:kind==='subscription'?{name:i.name||'',category:i.category||'',monthly:(i.registeredAmount??i.monthly)?groupDigits(String(i.registeredAmount??i.monthly)):'',date:i.renewal||''}:kind==='goal'?{name:i.name||'',monthly:i.monthly?groupDigits(String(i.monthly)):'',target:i.target?groupDigits(String(i.target)):'',saved:i.saved?groupDigits(String(i.saved)):'',date:i.targetDate||''}:kind==='income'?{category:i.category||'',origin:i.origin||'',monthly:(i.registeredAmount??i.monthly)?groupDigits(String(i.registeredAmount??i.monthly)):''}:kind==='expense'?{name:i.name||'',category:i.category||'',monthly:(i.registeredAmount??i.monthly)?groupDigits(String(i.registeredAmount??i.monthly)):'',interest:i.interest?groupDigits(String(i.interest)):'',principal:i.principal?groupDigits(String(i.principal)):'',provider:i.origin||''}:{});setCat(i.category||'Sparemål');setMoreInsurance(!!(i.bonus||i.coverageType||i.insuredValue||i.deductible||i.startDate||i.expiryDate||i.note));setExpenseGroup(kind==='expense'&&i.category?i.category:null);setIncomeGroup(kind==='income'&&i.category?(incomeTypes.find(([,items])=>items.includes(i.category))?.[0]||null):null);setSubscriptionGroup(kind==='subscription'&&i.category?i.category:null);setSubscriptionPeriod(kind==='subscription'?(i.registeredPeriod||'month'):'month');setShowSubscriptionDate(false);setInsurancePeriod(kind==='insurance'?(i.registeredPeriod||'month'):'month');setShowInsuranceStartDate(false);setShowInsuranceExpiryDate(false);setIncomePeriod(kind==='income'?(i.registeredPeriod||'month'):'month');setExpensePeriod(kind==='expense'?(i.registeredPeriod||'month'):'month')},[kind,initial]);
 if(!kind)return null;
 const submit=()=>{if(kind==='insurance'){const amount=num(f.monthly);const monthly=insurancePeriod==='quarter'?amount/3:insurancePeriod==='year'?amount/12:amount;return saveInsurance({type:f.name||'Forsikring',provider:f.provider||'Ikke registrert',monthly,registeredAmount:amount,registeredPeriod:insurancePeriod,coverage:f.coverageType||'',renewal:f.expiryDate||'',bonus:f.bonus,coverageType:f.coverageType,insuredValue:f.insuredValue,deductible:f.deductible,startDate:f.startDate,expiryDate:f.expiryDate,note:f.note})};if(kind==='subscription'){const amount=num(f.monthly);const monthly=subscriptionPeriod==='quarter'?amount/3:subscriptionPeriod==='year'?amount/12:amount;return saveSubscription({name:f.name||'Abonnement',category:f.category||'Annet',monthly,renewal:f.date||'',registeredAmount:amount,registeredPeriod:subscriptionPeriod})};if(kind==='goal')return saveGoal({name:f.name||cat,target:num(f.target),saved:num(f.saved),targetDate:f.date||'',category:cat,monthly:num(f.monthly)});if(kind==='income'){const amount=num(f.monthly);const monthly=incomePeriod==='quarter'?amount/3:incomePeriod==='year'?amount/12:amount;return saveIncome({name:f.category||'Inntekt',category:f.category||'Annen inntekt',monthly,registeredAmount:amount,registeredPeriod:incomePeriod,origin:f.origin||undefined})}const amount=f.name==='Boliglån'?num(f.interest)+num(f.principal):num(f.monthly);const period:Period=f.name==='Boliglån'?'month':expensePeriod;const monthly=period==='quarter'?amount/3:period==='year'?amount/12:amount;return saveExpense({name:f.name||'Utgift',category:f.category||'Annet',monthly,registeredAmount:amount,registeredPeriod:period,origin:f.category==='Forsikringer'?(f.provider||'Ikke registrert'):undefined,interest:f.name==='Boliglån'?num(f.interest):undefined,principal:f.name==='Boliglån'?num(f.principal):undefined})};
 const title=kind==='insurance'?'forsikring':kind==='subscription'?'abonnement':kind==='goal'?'sparing':kind==='income'?'inntekt':'utgift';
 return <Modal visible transparent animationType="slide"><KeyboardAvoidingView style={S.modalWrap} behavior={Platform.OS==='ios'?'padding':undefined}><Pressable style={S.backdrop} onPress={close}/><View style={S.modal}><View style={S.modalHead}><Text style={S.modalTitle}>{editing?'Rediger':'Legg til'} {title}</Text><Pressable onPress={close}><Ionicons name="close" size={24}/></Pressable></View><ScrollView keyboardShouldPersistTaps="handled">
 {kind==='income'?<><Text style={S.formLabel}>Inntektstype</Text>{!incomeGroup?<View style={S.categoryGrid}>{incomeTypes.map(([group])=><Pressable key={group} onPress={()=>setIncomeGroup(group)} style={S.categoryChoice}><Text style={S.categoryChoiceText}>{group}</Text></Pressable>)}</View>:<><Pressable onPress={()=>setIncomeGroup(null)} style={S.categoryBack}><Ionicons name="chevron-back" size={18} color={C.green}/><Text style={S.categoryBackText}>Alle kategorier</Text></Pressable><Text style={S.expenseSelectedTitle}>{incomeGroup}</Text><View style={S.expenseOptionList}>{(incomeTypes.find(([g])=>g===incomeGroup)?.[1]||[]).map(t=><Pressable key={t} onPress={()=>{set('category',/^Annen|^Annet/i.test(t)?'':t);if(t==='Lønn'&&incomePeriod==='quarter')setIncomePeriod('month')}} style={[S.expenseOption,f.category===t&&S.expenseOptionOn]}><Text style={[S.expenseOptionText,f.category===t&&S.expenseOptionTextOn]}>{t}</Text>{f.category===t?<Ionicons name="checkmark" size={20} color={C.white}/>:null}</Pressable>)}</View></>}{incomeGroup==='Annet'?<TextInput value={f.category||''} onChangeText={v=>set('category',v)} placeholder="Skriv egen inntektstype" style={S.input}/>:null}<Text style={S.formLabel}>Beløpet gjelder</Text><View style={S.chips}>{(f.category==='Lønn'?([['month','Månedslønn'],['year','Årslønn']] as const):([['month','Per måned'],['quarter','Per kvartal'],['year','Per år']] as const)).map(([v,l])=><Pressable key={v} onPress={()=>setIncomePeriod(v)} style={[S.chip,incomePeriod===v&&S.chipOn]}><Text style={[S.chipText,incomePeriod===v&&S.chipTextOn]}>{l}</Text></Pressable>)}</View><TextInput value={f.monthly||''} onChangeText={v=>set('monthly',groupDigits(v))} placeholder={incomePeriod==='year'?(f.category==='Lønn'?"Årslønn":"Beløp per år"):incomePeriod==='quarter'?"Beløp per kvartal":(f.category==='Lønn'?"Beløp utbetalt per måned":"Beløp per måned")} keyboardType="number-pad" style={S.input}/><TextInput value={f.origin||''} onChangeText={v=>set('origin',v)} placeholder="Utbetaler eller kilde (valgfritt)" style={S.input}/></>:null}
 {kind==='expense'?<><Text style={S.formLabel}>Utgiftstype</Text>{!expenseGroup?<View style={S.categoryGrid}>{expenseTypes.map(([group])=><Pressable key={group} onPress={()=>setExpenseGroup(group)} style={S.categoryChoice}><View style={S.categoryIcon}><Ionicons name={group==='Bolig'?'home-outline':group==='Forsikringer'?'shield-checkmark-outline':group==='Abonnement'?'repeat-outline':group==='Mat og husholdning'?'basket-outline':group==='Barn'?'people-outline':group==='Transport'?'car-outline':group==='Gjeld'?'card-outline':group==='Helse og fritid'?'heart-outline':'ellipsis-horizontal-outline'} size={18} color={C.green}/></View><Text style={S.categoryChoiceText}>{group}</Text></Pressable>)}</View>:<><Pressable onPress={()=>setExpenseGroup(null)} style={S.categoryBack}><Ionicons name="chevron-back" size={18} color={C.green}/><Text style={S.categoryBackText}>Alle kategorier</Text></Pressable><Text style={S.expenseSelectedTitle}>{expenseGroup}</Text><View style={S.expenseOptionList}>{(expenseTypes.find(([g])=>g===expenseGroup)?.[1]||[]).map(t=><Pressable key={t} onPress={()=>setF(x=>({...x,name:/^Annen|^Annet/i.test(t)?'':t,category:expenseGroup}))} style={[S.expenseOption,f.name===t&&S.expenseOptionOn]}><Text style={[S.expenseOptionText,f.name===t&&S.expenseOptionTextOn]}>{t}</Text>{f.name===t?<Ionicons name="checkmark" size={20} color={C.white}/>:null}</Pressable>)}</View></>}{expenseGroup==='Forsikringer'?<><Text style={S.formLabel}>Forsikringsselskap</Text><View style={S.suggestionWrap}>{insuranceProviders.map(t=><Pressable key={t} onPress={()=>set('provider',t==='Annet selskap'?'':t)} style={[S.suggestionChip,f.provider===t&&S.suggestionChipOn]}><Text style={[S.suggestionText,f.provider===t&&S.suggestionChipOn]}>{t}</Text></Pressable>)}</View><TextInput value={f.provider||''} onChangeText={v=>set('provider',v)} placeholder="Skriv forsikringsselskap" style={S.input}/></>:null}{f.name==='Boliglån'?<View style={S.mortgageBox}><Text style={S.formLabel}>Fordel boliglånet</Text><TextInput value={f.interest||''} onChangeText={v=>set('interest',groupDigits(v))} placeholder="Renter per måned" keyboardType="number-pad" style={S.input}/><TextInput value={f.principal||''} onChangeText={v=>set('principal',groupDigits(v))} placeholder="Avdrag per måned" keyboardType="number-pad" style={S.input}/><TextInput value={groupDigits(String(num(f.interest)+num(f.principal)))} editable={false} placeholder="Total termin per måned" style={S.input}/></View>:null}<TextInput value={f.name||''} onChangeText={v=>set('name',v)} placeholder={expenseGroup&&f.name===''?"Skriv egen utgiftstype":"Eget navn (valgfritt)"} style={S.input}/>{f.name!=='Boliglån'?<><Text style={S.formLabel}>Kostnaden gjelder</Text><View style={S.chips}>{([['month','Per måned'],['quarter','Per kvartal'],['year','Per år']] as const).map(([v,l])=><Pressable key={v} onPress={()=>setExpensePeriod(v)} style={[S.chip,expensePeriod===v&&S.chipOn]}><Text style={[S.chipText,expensePeriod===v&&S.chipTextOn]}>{l}</Text></Pressable>)}</View><TextInput value={f.monthly||''} onChangeText={v=>set('monthly',groupDigits(v))} placeholder={expensePeriod==='quarter'?"Kostnad per kvartal":expensePeriod==='year'?"Kostnad per år":"Kostnad per måned"} keyboardType="number-pad" style={S.input}/></>:null}</>:null}
 {kind==='insurance'?<><Text style={S.formLabel}>Type forsikring</Text><View style={S.suggestionWrap}>{insuranceTypes.map(t=><Pressable key={t} onPress={()=>set('name',/^Annen/i.test(t)?'':t)} style={[S.suggestionChip,f.name===t&&S.suggestionChipOn]}><Text style={[S.suggestionText,f.name===t&&S.suggestionTextOn]}>{t}</Text></Pressable>)}</View><TextInput value={f.name||''} onChangeText={v=>set('name',v)} placeholder="Skriv type forsikring" style={S.input}/><Text style={S.formLabel}>Forsikringsselskap</Text><View style={S.suggestionWrap}>{insuranceProviders.map(t=><Pressable key={t} onPress={()=>set('provider',t==='Annet selskap'?'':t)} style={[S.suggestionChip,f.provider===t&&S.suggestionChipOn]}><Text style={[S.suggestionText,f.provider===t&&S.suggestionChipOn]}>{t}</Text></Pressable>)}</View><TextInput value={f.provider||''} onChangeText={v=>set('provider',v)} placeholder="Skriv forsikringsselskap" style={S.input}/><Text style={S.formLabel}>Premien gjelder</Text><View style={S.chips}>{([['month','Per måned'],['quarter','Per kvartal'],['year','Per år']] as const).map(([v,l])=><Pressable key={v} onPress={()=>setInsurancePeriod(v)} style={[S.chip,insurancePeriod===v&&S.chipOn]}><Text style={[S.chipText,insurancePeriod===v&&S.chipTextOn]}>{l}</Text></Pressable>)}</View><TextInput value={f.monthly||''} onChangeText={v=>set('monthly',groupDigits(v))} placeholder={insurancePeriod==='quarter'?'Premie per kvartal':insurancePeriod==='year'?'Premie per år':'Premie per måned'} keyboardType="number-pad" style={S.input}/><Pressable onPress={()=>setMoreInsurance(v=>!v)} style={S.moreButton}><Text style={S.moreButtonText}>{moreInsurance?'Skjul detaljer':'Flere detaljer'}</Text></Pressable>{moreInsurance?<><TextInput value={f.bonus||''} onChangeText={v=>set('bonus',v)} placeholder="Bonus" style={S.input}/><TextInput value={f.coverageType||''} onChangeText={v=>set('coverageType',v)} placeholder="Dekningstype" style={S.input}/><TextInput value={f.insuredValue||''} onChangeText={v=>set('insuredValue',groupDigits(v))} placeholder="Forsikringssum" keyboardType="number-pad" style={S.input}/><TextInput value={f.deductible||''} onChangeText={v=>set('deductible',groupDigits(v))} placeholder="Egenandel" keyboardType="number-pad" style={S.input}/><Text style={S.formLabel}>Tegningsdato</Text><Pressable onPress={()=>{Keyboard.dismiss();setShowInsuranceStartDate(true)}} accessibilityRole="button" accessibilityLabel="Velg tegningsdato" style={S.datePickerButton}><Text style={f.startDate?S.datePickerValue:S.datePickerPlaceholder}>{f.startDate||'Velg tegningsdato'}</Text><Ionicons name="calendar-outline" size={21} color={C.green}/></Pressable>{showInsuranceStartDate?<DateTimePicker value={parseDate(f.startDate)||new Date()} mode="date" display={Platform.OS==='ios'?'spinner':'default'} onValueChange={(_,d)=>{if(d)set('startDate',dateText(d))}} onDismiss={()=>setShowInsuranceStartDate(false)}/>:null}<Text style={S.formLabel}>Fornyelses-/utløpsdato</Text><Pressable onPress={()=>{Keyboard.dismiss();setShowInsuranceExpiryDate(true)}} accessibilityRole="button" accessibilityLabel="Velg fornyelses- eller utløpsdato" style={S.datePickerButton}><Text style={f.expiryDate?S.datePickerValue:S.datePickerPlaceholder}>{f.expiryDate||'Velg fornyelses-/utløpsdato'}</Text><Ionicons name="calendar-outline" size={21} color={C.green}/></Pressable>{showInsuranceExpiryDate?<DateTimePicker value={parseDate(f.expiryDate)||new Date()} mode="date" display={Platform.OS==='ios'?'spinner':'default'} onValueChange={(_,d)=>{if(d)set('expiryDate',dateText(d))}} onDismiss={()=>setShowInsuranceExpiryDate(false)}/>:null}<TextInput value={f.note||''} onChangeText={v=>set('note',v)} placeholder="Notat" style={S.input}/></>:null}</>:null}
 {kind==='subscription'?<><Text style={S.formLabel}>Kategori</Text>{!subscriptionGroup?<View style={S.categoryGrid}>{subscriptionTypes.map(([group])=><Pressable key={group} onPress={()=>{setSubscriptionGroup(group);set('category',group);set('name','')}} style={S.categoryChoice}><View style={S.categoryIcon}><Ionicons name={group==='TV / streaming'?'play-circle-outline':group==='Musikk'?'headset-outline':group==='Mobil'?'phone-portrait-outline':group==='Internett'?'wifi-outline':group==='Programvare'?'apps-outline':group==='Gaming'?'game-controller-outline':group==='Avis / nyheter'?'newspaper-outline':group==='Skylagring'?'cloud-outline':group==='Trening'?'fitness-outline':'ellipsis-horizontal-outline'} size={18} color={C.green}/></View><Text style={S.categoryChoiceText}>{group}</Text></Pressable>)}</View>:<><Pressable onPress={()=>{setSubscriptionGroup(null);set('category','');set('name','')}} style={S.categoryBack}><Ionicons name="chevron-back" size={18} color={C.green}/><Text style={S.categoryBackText}>Alle kategorier</Text></Pressable><Text style={S.expenseSelectedTitle}>{subscriptionGroup}</Text><View style={S.expenseOptionList}>{(subscriptionTypes.find(([g])=>g===subscriptionGroup)?.[1]||[]).map(t=><Pressable key={t} onPress={()=>set('name',/^Annen|^Annet/i.test(t)?'':t)} style={[S.expenseOption,f.name===t&&S.expenseOptionOn]}><Text style={[S.expenseOptionText,f.name===t&&S.expenseOptionTextOn]}>{t}</Text>{f.name===t?<Ionicons name="checkmark" size={20} color={C.white}/>:null}</Pressable>)}</View></>}<TextInput value={f.name||''} onChangeText={v=>set('name',v)} placeholder={subscriptionGroup==='Annet'||f.name===''?"Skriv navn på abonnement":"Navn på abonnement"} style={S.input}/><Text style={S.formLabel}>Betalingsperiode</Text><View style={S.chips}>{([['month','Per måned'],['quarter','Per kvartal'],['year','Per år']] as const).map(([v,l])=><Pressable key={v} onPress={()=>setSubscriptionPeriod(v)} style={[S.chip,subscriptionPeriod===v&&S.chipOn]}><Text style={[S.chipText,subscriptionPeriod===v&&S.chipTextOn]}>{l}</Text></Pressable>)}</View><TextInput value={f.monthly||''} onChangeText={v=>set('monthly',groupDigits(v))} placeholder={subscriptionPeriod==='quarter'?'Kostnad per kvartal':subscriptionPeriod==='year'?'Kostnad per år':'Kostnad per måned'} keyboardType="number-pad" style={S.input}/><Text style={S.formLabel}>Neste betaling / fornyelse</Text><Pressable onPress={()=>{Keyboard.dismiss();setShowSubscriptionDate(true)}} accessibilityRole="button" accessibilityLabel="Velg neste betaling eller fornyelse" style={S.datePickerButton}><Text style={f.date?S.datePickerValue:S.datePickerPlaceholder}>{f.date||'Velg dato'}</Text><Ionicons name="calendar-outline" size={21} color={C.green}/></Pressable>{showSubscriptionDate?<DateTimePicker value={parseDate(f.date)||new Date()} mode="date" display={Platform.OS==='ios'?'spinner':'default'} onValueChange={(_,d)=>{if(d)set('date',dateText(d))}} onDismiss={()=>setShowSubscriptionDate(false)}/>:null}</>:null}
 {kind==='goal'?<><Text style={S.formLabel}>Type sparing</Text><View style={S.chips}>{(['Sparemål','Buffer','Fond','Aksjer','Pensjon'] as GoalCategory[]).map(x=><Pressable key={x} onPress={()=>setCat(x)} style={[S.chip,cat===x&&S.chipOn]}><Text style={[S.chipText,cat===x&&S.chipTextOn]}>{x}</Text></Pressable>)}</View><TextInput value={f.name||''} onChangeText={v=>set('name',v)} placeholder="Navn" style={S.input}/><TextInput value={f.monthly||''} onChangeText={v=>set('monthly',groupDigits(v))} placeholder="Fast månedlig sparing" keyboardType="number-pad" style={S.input}/>{goalUsesTarget(cat)?<TextInput value={f.target||''} onChangeText={v=>set('target',groupDigits(v))} placeholder="Målbeløp" keyboardType="number-pad" style={S.input}/>:<View style={S.goalOptionalNote}><Text style={S.noteText}>Målbeløp er valgfritt for {cat.toLowerCase()}. All registrert sparing vises uansett.</Text></View>}<TextInput value={f.saved||''} onChangeText={v=>set('saved',groupDigits(v))} placeholder="Allerede spart" keyboardType="number-pad" style={S.input}/>{goalUsesTarget(cat)?<><Pressable onPress={()=>{Keyboard.dismiss();setShowGoalDate(true)}} accessibilityRole="button" accessibilityLabel="Velg måldato" style={S.datePickerButton}><Text style={f.date?S.datePickerValue:S.datePickerPlaceholder}>{f.date||'Velg måldato'}</Text><Ionicons name="calendar-outline" size={21} color={C.green}/></Pressable>{showGoalDate?<DateTimePicker value={parseDate(f.date)||new Date()} mode="date" display={Platform.OS==='ios'?'spinner':'default'} onValueChange={(_,d)=>{if(d)set('date',dateText(d))}} onDismiss={()=>setShowGoalDate(false)}/>:null}</>:null}</>:null}
 <Pressable onPress={submit} accessibilityRole="button" style={S.primary}><Text style={S.primaryText}>{editing?'Lagre endringer':'Lagre'}</Text></Pressable></ScrollView></View></KeyboardAvoidingView></Modal>}

function Nav({active,go}:{active:Tab;go:(t:Tab)=>void}){return <View style={S.nav}>{tabs.map(x=><Pressable key={x.name} onPress={()=>go(x.name)} accessibilityRole="tab" accessibilityState={{selected:active===x.name}} accessibilityLabel={x.name} style={[S.navItem,active===x.name&&S.navItemOn]}><Ionicons name={x.icon} size={21} color={active===x.name?C.green:C.muted}/><Text numberOfLines={1} style={[S.navText,active===x.name&&S.navOn]}>{x.name}</Text></Pressable>)}</View>}
function MonthMetric({icon,label,value}:{icon:Icon;label:string;value:string}){return <View style={S.monthMetric}><View style={S.monthMetricIcon}><Ionicons name={icon} size={19} color={C.green}/></View><Text style={S.monthMetricLabel}>{label}</Text><Text style={S.monthMetricValue}>{value}</Text></View>}
function Tile({icon,title,value,sub,onPress}:{icon:Icon;title:string;value:string;sub:string;onPress:()=>void}){return <Pressable onPress={onPress} style={S.tile}><View style={S.icon}><Ionicons name={icon} size={22} color={C.green}/></View><View style={S.flex}><Text style={S.cardTitle}>{title}</Text><Text style={S.cardSub}>{sub}</Text></View><Text style={S.value}>{value}</Text></Pressable>}
function Section({title,action,onPress}:{title:string;action?:string;onPress?:()=>void}){return <View style={S.section}><Text style={S.sectionTitle}>{title}</Text>{action&&<Pressable onPress={onPress} style={S.add}><Ionicons name="add" size={18} color={C.green}/><Text style={S.addText}>{action}</Text></Pressable>}</View>}
function Summary({k,a,d}:{k:string;a:string;d:string}){return <View style={S.summary}><Text style={S.kicker}>{k}</Text><Text style={S.summaryAmount}>{a}</Text><Text style={S.summaryText}>{d}</Text></View>}
function Detail({l,v}:{l:string;v:string}){return <View style={S.detail}><Text style={S.detailLabel}>{l}</Text><Text style={S.detailValue}>{v}</Text></View>}
function Trash({onPress}:{onPress:()=>void}){return <Pressable onPress={onPress} accessibilityRole="button" accessibilityLabel="Slett" style={S.trash}><Ionicons name="trash-outline" size={18} color={C.red}/></Pressable>}
function Progress({val}:{val:number}){return <View style={S.track}><View style={[S.fill,{width:`${Math.min(100,val)}%`}]}/></View>}
function Stat({l,v}:{l:string;v:string}){return <View style={S.flex}><Text style={S.statLabel}>{l}</Text><Text style={S.statValue}>{v}</Text></View>}
